#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int *arr = calloc(n, sizeof(int));
    if (arr == NULL) { perror("calloc"); return 1; }
    for (int i = 0; i < n; i++) {
        printf("%d", arr[i]);
        if (i + 1 < n) printf(" ");
    }
    printf("\n");
    free(arr);
    return 0;
}

