#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;

    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 1;
        Node *nd = malloc(sizeof(Node));
        if (nd == NULL) return 1;
        nd->value = x;
        nd->next = NULL;
        if (tail) tail->next = nd; else head = nd;
        tail = nd;
    }

    for (Node *cur = head; cur; cur = cur->next) {
        printf("%d", cur->value);
        if (cur->next) printf(" ");
    }
    printf("\n");

    for (Node *cur = head; cur; ) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
    return 0;
}
